import{_ as o,o as t,c as d,a2 as r}from"./chunks/framework.B8TleWq7.js";const p=JSON.parse('{"title":"Folders and boot","description":"","frontmatter":{},"headers":[],"relativePath":"guides/boot-and-folders.md","filePath":"guides/boot-and-folders.md"}'),a={name:"guides/boot-and-folders.md"};function c(s,e,l,i,n,h){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="folders-and-boot" tabindex="-1">Folders and boot <a class="header-anchor" href="#folders-and-boot" aria-label="Permalink to &quot;Folders and boot&quot;">​</a></h1><p>How the code is laid out on disk and in Studio, and how each side starts.</p><h2 id="folder-roots" tabindex="-1">Folder roots <a class="header-anchor" href="#folder-roots" aria-label="Permalink to &quot;Folder roots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Disk folder</th><th>Studio Folder</th><th>Holds</th></tr></thead><tbody><tr><td><code>src/ReplicatedStorage/Keel/</code></td><td><code>ReplicatedStorage.Keel</code></td><td>Keel, shared parts (owned by Keel)</td></tr><tr><td><code>src/ReplicatedStorage/Shared/</code></td><td><code>ReplicatedStorage.Shared</code></td><td>this game&#39;s shared code: Defs, the Net list</td></tr><tr><td><code>src/ServerScriptService/KeelServer/</code></td><td><code>ServerScriptService.KeelServer</code></td><td>Keel, server-only parts (owned by Keel)</td></tr><tr><td><code>src/ServerScriptService/Server/</code></td><td><code>ServerScriptService.Server</code></td><td>this game&#39;s server code</td></tr><tr><td><code>src/ReplicatedFirst/Client/</code></td><td><code>ReplicatedFirst.Client</code></td><td>all of this game&#39;s client code</td></tr><tr><td><code>src/StarterPlayer/StarterPlayerScripts/Boot/</code></td><td><code>StarterPlayer.StarterPlayerScripts.Boot</code></td><td>only <code>Boot.local.luau</code></td></tr></tbody></table><p>The <strong>Keel Setup</strong> plugin creates these Folders for you. How to install it and connect them: <a href="/Keel-Docs/getting-started/connect-studio">Connect Roblox Studio</a>. The file-name rules (<code>.server.luau</code>, <code>.local.luau</code>, <code>init.luau</code>) are on that page too.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Empty folders hold a <code>.gitkeep</code> because Git does not keep empty folders. Script Sync ignores non-script files, so a folder with only a <code>.gitkeep</code> does not appear in Studio until its first <code>.luau</code> file is added. Delete the <code>.gitkeep</code> once the folder has real files.</p></div><h2 id="boot" tabindex="-1">Boot <a class="header-anchor" href="#boot" aria-label="Permalink to &quot;Boot&quot;">​</a></h2><p>Both sides boot through the <a href="/Keel-Docs/guides/loader-and-scheduler">Loader</a>.</p><h3 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h3><p><code>Server/Main.server.luau</code> is the only server Script. In order, it:</p><ol><li>Requires <code>Shared/Net</code>, <code>Keel/State/Messages</code> and <code>Keel/Purchases/Messages</code>, so every network message exists before any client asks.</li><li>Calls <code>Defs.Boot</code> on <code>Shared/Defs</code> and <code>Server/Defs</code>. In Studio a broken entry errors here and stops the boot.</li><li>Calls the <code>Configure</code> of the services that need the game&#39;s settings: <code>Data.Configure</code> (test places and migration steps), <code>LiveDefs.Configure</code> (live-config keys), <code>Purchases.Configure</code> (products, passes, subscriptions) and <code>Console.Configure</code> (the admin list).</li><li>Calls <code>Loader.Boot(&quot;Server&quot;, KeelServer, Server.Services, Server.Systems)</code>. All are booted together and sorted by <code>Dependencies</code>, so a game Service can depend on a KeelServer one. A folder missing in Studio is skipped.</li><li>Calls <code>Entity.Boot(Server.Components)</code>, which starts attaching components to tagged Instances.</li></ol><h3 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h3><ol><li><code>Boot.local.luau</code> waits for <code>game.Loaded</code>.</li><li>It requires <code>ReplicatedFirst.Client.Main</code> and calls <code>Start()</code>.</li><li><code>Main.Start()</code> requires <code>Shared/Net</code> and <code>Keel/Purchases/Messages</code>, calls <code>Defs.Boot</code> on <code>Shared/Defs</code>, and calls <code>Net.WaitForServer()</code>, which waits until the server has published every message. (<code>Loading.local.luau</code>, an early LocalScript, has already shown the loading screen.) Then <code>UIController.Boot</code> registers every View.</li><li>It calls <code>Loader.Boot(&quot;Client&quot;, Client.Controllers)</code>. Then <code>Entity.Boot(Client.Components)</code>.</li><li>It calls <code>State.Boot()</code>, then <code>Net.ClientReady()</code> (the server sends anything it held back for this player), then <code>Console.Start()</code>, and last <code>LoadingScreen.Hide()</code>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Nothing in <code>ReplicatedFirst</code> may run networking before boot. The networking library does not work if started from <code>ReplicatedFirst</code> that early. Only the loading screen runs early.</p></div>',14)])])}const S=o(a,[["render",c]]);export{p as __pageData,S as default};
